import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

/** Content is generated by `npm run import` (scripts/import-content.mjs) – edit there, not here. */

const lang = z.enum(['km', 'en', 'km+en']).default('km');

/** Seuksa articles: blog, quotes, stories, answers. id = "<section>/<slug>". */
const articles = defineCollection({
  loader: glob({
    pattern: '*/*.md',
    base: './src/content/seuksa',
    generateId: ({ entry }) => entry.replace(/\.md$/, ''),
  }),
  schema: z.object({
    title: z.string(),
    slug: z.string(),
    section: z.enum(['blog', 'quotes', 'stories', 'answers']),
    date: z.coerce.date(),
    updated: z.coerce.date().optional(),
    author: z.string().optional(),
    quoteAuthor: z.string().optional(),
    categories: z.array(z.string()).default([]),
    tags: z.array(z.string()).default([]),
    description: z.string().default(''),
    cover: z.string().optional(),
    lang,
    views: z.number().optional(),
    source: z.string().optional(),
  }),
});

/** Standalone Seuksa pages (postal codes, app privacy …). */
const pages = defineCollection({
  loader: glob({ pattern: '*.md', base: './src/content/pages' }),
  schema: z.object({
    title: z.string(),
    slug: z.string(),
    description: z.string().default(''),
    date: z.coerce.date().optional(),
    updated: z.coerce.date().optional(),
    lang,
    source: z.string().optional(),
  }),
});

/** Nitean books. id = book key. Body = copyright note. */
const books = defineCollection({
  loader: glob({
    pattern: '*/book.md',
    base: './src/content/nitean',
    generateId: ({ entry }) => entry.split('/')[0],
  }),
  schema: z.object({
    title: z.string(),
    subtitle: z.string().optional(),
    originalTitle: z.string().optional(),
    book: z.string(),
    order: z.number().default(99),
    lang,
    tone: z.enum(['amber', 'rose', 'emerald', 'sky', 'slate']).default('amber'),
    author: z.string().optional(),
    description: z.string().optional(),
    cover: z.string().optional(),
    chapters: z.number(),
    parts: z.array(z.object({ key: z.string(), title: z.string(), intro: z.string().optional() })).default([]),
    source: z.string().optional(),
  }),
});

/** Book chapters in reading order (seq). id = "<book>/<slug>". */
const chapters = defineCollection({
  loader: glob({
    pattern: '*/chapters/*.md',
    base: './src/content/nitean',
    generateId: ({ entry, data }) => `${entry.split('/')[0]}/${data.slug}`,
  }),
  schema: z.object({
    title: z.string(),
    slug: z.string(),
    book: z.string(),
    kind: z.enum(['front', 'chapter', 'back']),
    part: z.string().optional(),
    seq: z.number(),
    lang,
    date: z.coerce.date().optional(),
    updated: z.coerce.date().optional(),
    description: z.string().default(''),
    source: z.string().optional(),
  }),
});

export const collections = { articles, pages, books, chapters };
